33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit logger; each successful owner create emits one line here. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        String address = normalizeAddress(owner.getAddress());
117	        if (address.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        owner.setAddress(address);
121	        String telephone = toE164(owner.getTelephone());
122	        if (telephone == null) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        if (owner.getEmail() != null) {
126	            String email = normalizeEmail(owner.getEmail());
127	            if (email == null) {
128	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	            }
130	            owner.setEmail(email);
131	        }
132	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
133	        if (effectiveRegistrationDate == null) {
134	            effectiveRegistrationDate = LocalDate.now();
135	        }
136	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
137	        owner.setRegistrationDate(registrationDate);
138	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        for (Owner existing : this.clinicService.findAllOwners()) {
145	            if (telephone.equals(toE164(existing.getTelephone()))) {
146	                return new ResponseEntity<>(HttpStatus.CONFLICT);
147	            }
148	        }
149	        String lastNameKey = householdKey(owner.getLastName());
150	        String addressKey = householdKey(owner.getAddress());
151	        List<Owner> householdMembers = new ArrayList<>();
152	        for (Owner existing : this.clinicService.findAllOwners()) {
153	            if (lastNameKey.equals(householdKey(existing.getLastName()))
154	                && addressKey.equals(householdKey(existing.getAddress()))) {
155	                householdMembers.add(existing);
156	            }
157	        }
158	        if (!householdMembers.isEmpty()) {
159	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
160	                return new ResponseEntity<>(HttpStatus.CONFLICT);
161	            }
162	            String householdId = householdId(lastNameKey, addressKey);
163	            owner.setHouseholdId(householdId);
164	            for (Owner member : householdMembers) {
165	                if (!householdId.equals(member.getHouseholdId())) {
166	                    member.setHouseholdId(householdId);
167	                    this.clinicService.saveOwner(member);
168	                }
169	            }
170	        }
171	        owner.setTelephone(telephone);
172	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
173	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
174	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
175	        this.clinicService.saveOwner(owner);
176	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
177	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
251	        HttpHeaders headers = new HttpHeaders();
252	        Visit visit = visitMapper.toVisit(visitFieldsDto);
253	        Pet pet = new Pet();
254	        pet.setId(petId);
255	        visit.setPet(pet);
256	        this.clinicService.saveVisit(visit);
257	        VisitDto visitDto = visitMapper.toVisitDto(visit);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
259	            .buildAndExpand(visit.getId()).toUri());
260	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
261	    }
262	
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner != null) {
269	            Pet pet = owner.getPet(petId);
270	            if (pet != null) {
271	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	
277	    /**
278	     * The maximum number of owners permitted per city. Owner creation is rejected once the
279	     * owner's city already contains this many owners.
280	     */
281	    private static final int MAX_OWNERS_PER_CITY = 50;
282	
283	    /**
284	     * Counts how many existing owners live in the given city, compared case-insensitively.
285	     * This is evaluated before the new owner is persisted, so the owner being created is not
286	     * included in the count.
287	     *
288	     * @param city the new owner's city
289	     * @return the number of existing owners in that city
290	     */
291	    private int countOwnersInCity(String city) {
292	        int count = 0;
293	        for (Owner existing : this.clinicService.findAllOwners()) {
294	            if (city.equalsIgnoreCase(existing.getCity())) {
295	                count++;
296	            }
297	        }
298	        return count;
299	    }
300	
301	    /**
302	     * The maximum number of owners that may be created in a single business day. Owner
303	     * creation is rejected once this many owners already fall on the new owner's adjusted
304	     * business day {@code registrationDate}.
305	     */
306	    private static final int MAX_OWNERS_PER_DAY = 100;
307	
308	    /**
309	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
310	     * to the following Monday, while a weekday is returned unchanged.
311	     *
312	     * @param date the date to adjust
313	     * @return the same date if it is a weekday, otherwise the following Monday
314	     */
315	    private LocalDate toBusinessDay(LocalDate date) {
316	        DayOfWeek dayOfWeek = date.getDayOfWeek();
317	        if (dayOfWeek == DayOfWeek.SATURDAY) {
318	            return date.plusDays(2);
319	        }
320	        if (dayOfWeek == DayOfWeek.SUNDAY) {
321	            return date.plusDays(1);
322	        }
323	        return date;
324	    }
325	
326	    /**
327	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
328	     * registrationDate} rolls forward to the same business day. This is evaluated before the
329	     * new owner is persisted, so the owner being created is not included in the count.
330	     *
331	     * @param businessDay the adjusted business day to count against
332	     * @return the number of existing owners registered on that business day
333	     */
334	    private int countOwnersRegisteredOn(LocalDate businessDay) {
335	        int count = 0;
336	        for (Owner existing : this.clinicService.findAllOwners()) {
337	            LocalDate existingDate = existing.getRegistrationDate();
338	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
339	                count++;
340	            }
341	        }
342	        return count;
343	    }
344	
345	    /**
346	     * Builds the customer code for a newly created owner, formatted
347	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
348	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
349	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
350	     * to one more than the number of owners already in that city.
351	     *
352	     * @param city     the owner's city
353	     * @param lastName the owner's last name
354	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
355	     */
356	    private String nextCustomerCode(String city, String lastName) {
357	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
358	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
359	        int sequence = 1;
360	        for (Owner existing : this.clinicService.findAllOwners()) {
361	            if (city.equalsIgnoreCase(existing.getCity())) {
362	                sequence++;
363	            }
364	        }
365	        return String.format("%s-%s-%04d", city3, last3, sequence);
366	    }
367	
368	    /**
369	     * Builds the membership number for a newly created owner, formatted
370	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
371	     * customer code and {@code YY} is the last two digits of the owner's registration
372	     * date year, zero-padded to two digits.
373	     *
374	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
375	     * @param registrationDate the owner's registration date
376	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
377	     */
378	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
379	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
380	    }
381	
382	    /**
383	     * Counts how many existing owners share the given first and last name, compared
384	     * case-insensitively. This is evaluated before the new owner is persisted, so the
385	     * owner being created is not included in the count.
386	     *
387	     * @param firstName the new owner's first name
388	     * @param lastName  the new owner's last name
389	     * @return the number of existing owners with the same first and last name
390	     */
391	    private int countNamesakes(String firstName, String lastName) {
392	        int count = 0;
393	        for (Owner existing : this.clinicService.findAllOwners()) {
394	            if (firstName.equalsIgnoreCase(existing.getFirstName())
395	                && lastName.equalsIgnoreCase(existing.getLastName())) {
396	                count++;
397	            }
398	        }
399	        return count;
400	    }
401	
402	    /**
403	     * Canonical expansions applied to common street-type abbreviations during address
404	     * normalization. Keys and values are upper-cased so the lookup runs after the address
405	     * has itself been upper-cased.
406	     */
407	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
408	        "ST", "STREET",
409	        "RD", "ROAD",
410	        "AVE", "AVENUE");
411	
412	    /**
413	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
414	     * every run of internal whitespace is collapsed to a single space, the result is
415	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
416	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
417	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
418	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
419	     * returned and compared for household duplicates; an address that is blank once
420	     * normalized fails the required-field check.
421	     *
422	     * @param address the raw address value supplied by the client
423	     * @return the normalized address (empty string when {@code address} is null or blank)
424	     */
425	    private static String normalizeAddress(String address) {
426	        if (address == null) {
427	            return "";
428	        }
429	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
430	        if (collapsed.isEmpty()) {
431	            return "";
432	        }
433	        StringBuilder normalized = new StringBuilder(collapsed.length());
434	        for (String token : collapsed.split(" ")) {
435	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
436	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
437	            if (normalized.length() > 0) {
438	                normalized.append(' ');
439	            }
440	            normalized.append(expanded != null ? expanded : token);
441	        }
442	        return normalized.toString();
443	    }
444	
445	    /**
446	     * Normalizes a last name or address for household-duplicate comparison: leading and
447	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
448	     * single space and the result is lower-cased. Two owners are considered to share a
449	     * household when both their last names and addresses produce the same key.
450	     *
451	     * @param value the raw last name or address value
452	     * @return the normalized comparison key (empty string when {@code value} is null)
453	     */
454	    private static String householdKey(String value) {
455	        if (value == null) {
456	            return "";
457	        }
458	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
459	    }
460	
461	    /**
462	     * Derives the stable shared household identifier for the given normalized last name
463	     * and address keys. The identifier is deterministic — the same household (same
464	     * {@link #householdKey normalized} last name and address) always maps to the same
465	     * value — so every owner who joins a household is assigned an identical id. It is the
466	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
467	     * '<lastNameKey>|<addressKey>'}.
468	     *
469	     * @param lastNameKey the normalized last name key
470	     * @param addressKey  the normalized address key
471	     * @return the shared household identifier
472	     */
473	    private static String householdId(String lastNameKey, String addressKey) {
474	        String source = lastNameKey + "|" + addressKey;
475	        try {
476	            byte[] digest = MessageDigest.getInstance("SHA-256")
477	                .digest(source.getBytes(StandardCharsets.UTF_8));
478	            StringBuilder hex = new StringBuilder(digest.length * 2);
479	            for (byte b : digest) {
480	                hex.append(String.format("%02x", b));
481	            }
482	            return hex.substring(0, 12).toUpperCase();
483	        } catch (NoSuchAlgorithmException e) {
484	            throw new IllegalStateException("SHA-256 not available", e);
485	        }
486	    }
487	
488	    /**
489	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
490	     * and brackets are stripped. When the number already carries a leading {@code '+'}
491	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
492	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
493	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
494	     *
495	     * @param telephone the raw telephone value supplied by the client
496	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
497	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
498	     */
499	    private static String toE164(String telephone) {
500	        if (telephone == null) {
501	            return null;
502	        }
503	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
504	        String digits;
505	        if (cleaned.startsWith("+")) {
506	            digits = cleaned.substring(1);
507	        } else {
508	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
509	            digits = "61" + national;
510	        }
511	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
512	    }
513	
514	    /**
515	     * Normalizes an owner email for creation. A present email must be a syntactically
516	     * valid address; the returned value is lower-cased.
517	     *
518	     * @param email the raw email value supplied by the client (never {@code null} here)
519	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
520	     *         address (signalling a 400 Bad Request)
521	     */
522	    private static String normalizeEmail(String email) {
523	        String trimmed = email.trim();
524	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
525	            return null;
526	        }
527	        return trimmed.toLowerCase();
528	    }
